#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int minEatingSpeed(int* piles, int n, int h) {
    int lo = 1, hi = 0;
    for (int i = 0; i < n; i++) if (piles[i] > hi) hi = piles[i];

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long hours = 0;
        for (int i = 0; i < n; i++) {
            hours += (piles[i] + (long long)mid - 1) / mid;
            if (hours > h) break;
        }
        if (hours <= h) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    long long vals[10001];
    int count = 0;
    char *p = line;
    while (*p) {
        if ((*p >= '0' && *p <= '9') || *p == '-') {
            char *end;
            vals[count++] = strtoll(p, &end, 10);
            p = end;
        } else {
            p++;
        }
    }

    int h = (int)vals[count - 1];
    int n = count - 1;
    int *piles = (int*)malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; i++) piles[i] = (int)vals[i];

    printf("%d\n", minEatingSpeed(piles, n, h));
    free(piles);
    return 0;
}

