import java.io.*;
import java.util.*;

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int lo = 1, hi = 0;
        for (int p : piles) hi = Math.max(hi, p);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long hours = 0;
            for (int p : piles) hours += (p + (long)mid - 1) / mid;
            if (hours <= h) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim().replaceAll("[\\[\\],]", " ").trim();
        String[] a = s.split("\\s+");
        int[] piles = new int[a.length - 1];
        for (int i = 0; i < piles.length; i++) piles[i] = Integer.parseInt(a[i]);
        int h = Integer.parseInt(a[a.length - 1]);
        System.out.println(new Solution().minEatingSpeed(piles, h));
    }
}

